/* Service policies guide manual selection and order helper work. Rework retains original arrival time. */
const SERVICE_RULES={fifo:{name:'First come, first served',detail:'Prioritize tickets in the order they joined the work queue. A returned order rejoins at the back.'},quick:{name:'Quick orders first',detail:'Prioritize the order with the least estimated work remaining. Larger orders can wait longer.'},longest:{name:'Longest wait first',detail:'Prioritize the earliest original arrival, including customers whose orders came back. This matches first-come-first-served until a return changes the ticket order.'}};
const ServiceBase=CampaignCafe;
CampaignCafe=class extends ServiceBase{
 constructor(...args){super(...args);this.duration=300;this.arrivals=this.arrivals.filter(t=>t<this.duration);this.policy=journey.serviceRule||'fifo';this.returns=0;this.remakeCost=0;this.remakeSeconds=0;}
 remaining(o){let drink=0;if(o.recipe.coffee){for(const k of ['syrup','milk','coffee'])if(o.fills[k]===undefined)drink+=5+(FILL_TARGETS[k]-this.baseLevel(k,o))/(18*(this.upgrades.has(k)?1.35:1));if(!o.lid)drink+=8;}const slot=this.ovenSlots.find(s=>s?.id===o.id);const food=!o.recipe.bakery||o.bakeryResult?0:slot?Math.max(0,slot.duration-this.time+slot.started)+2:(this.upgrades.has('oven')?25:45)+4;return Math.max(drink,food)+(o.accepted?0:3)+2;}
 priorityOrders(){const rank=o=>this.policy==='quick'?this.remaining(o):this.policy==='longest'?o.arrived:(o.requeuedAt??o.arrived);return [...this.orders].sort((a,b)=>rank(a)-rank(b)||(this.policy==='fifo'?(a.queueSequence??a.id)-(b.queueSequence??b.id):a.id-b.id));}
 recommendation(){return this.priorityOrders()[0]||null;}
 tick(dt){if(this.policy){this.orders=this.priorityOrders();if(this.activity&&this.active?.isRemake)this.remakeSeconds+=Math.min(dt,this.duration-this.time);}super.tick(dt);this.orders.sort((a,b)=>a.arrived-b.arrived||a.id-b.id);}
 serve(o=this.active,byHelper=false){if(!this.ready(o))return null;const s=this.scores(o);const badDrink=o.recipe.coffee&&(s.coffeeAccuracy<90||(o.presentationScore??100)<80),badFood=o.recipe.bakery&&s.bakeryAccuracy<90;if(badDrink||badFood){const cost=(badDrink?1.15:0)+(badFood?(o.recipe.bakery==='Breakfast Sandwich'?1.3:.6):0);this.costs+=cost;this.remakeCost+=cost;this.returns++;o.returnCount=(o.returnCount||0)+1;o.isRemake=true;o.requeuedAt=this.time;o.queueSequence=this.id+this.returns;o.returnReason=[badDrink?((o.presentationScore??100)<80?'topping presentation below 80%':'drink accuracy below 90%'):'',badFood?(o.bakeryResult?.burned?'burned bakery item':'bakery quality below 90%'):''].filter(Boolean).join(' and ');if(badDrink)this.retry('syrup',o);if(badFood){o.bakeryResult=null;o.progress.baking=0;}o.accepted=true;this.activeId=this.recommendation()?.id??o.id;return {...s,id:o.id,name:o.name,tip:0,rework:true,cost};}const r=super.serve(o,byHelper);if(r){r.returnCount=o.returnCount||0;this.activeId=this.recommendation()?.id??null;}return r;}
 statusFor(o){const s=super.statusFor(o);return o.isRemake?'↻ Remake · '+s:s;}
 report(){const r=super.report();return {...r,policy:this.policy||'fifo',returns:this.returns||0,remakeCost:this.remakeCost||0,remakeSeconds:this.remakeSeconds||0,longestWait:Math.max(0,...this.served.map(o=>o.wait)),longestUnfinished:Math.max(0,...this.orders.map(o=>this.time-o.arrived)),pendingRemakes:this.orders.filter(o=>o.isRemake).length};}
};
metricRows.splice(1,0,['longestWait','Longest completed-customer wait','s',false]);
const serviceStart=start,serviceRender=render,serviceUpdate=update,serviceShop=showShop,serviceReport=showReport,serviceBegin=beginCampaignShift,serviceTutorialHandoff=handoff;
start=function(){journey.serviceRule='fifo';serviceStart();};
beginCampaignShift=function(){serviceBegin();const body=document.querySelector('.learning-card p');if(body)body.insertAdjacentHTML('beforeend',`<br><br><b>Shift length: 5:00.</b> Service rule: ${SERVICE_RULES[sim.policy].name}. Orders below 90% drink or bakery accuracy come back for a remake. Their original waiting timer keeps running.`);};
render=function(){serviceRender();const e=document.querySelector('.economy');e.style.visibility='visible';e.classList.add('service-strip');e.innerHTML='<span id="economy" hidden></span><span id="service-policy-label"></span><button id="next-priority" class="small-btn">Next suggested order →</button><span id="remake-alert" role="status"></span>';document.querySelector('#next-priority').onclick=()=>{const o=sim.recommendation?.();if(o){selectCustomer(o.id);document.querySelector('#take-order')?.focus();}};update();};
update=function(){serviceUpdate();if(!sim||sim.finished||!document.querySelector('#service-policy-label'))return;const strip=document.querySelector('.service-strip');strip.hidden=!!sim.tutorial;if(sim.tutorial)return;document.querySelector('#time-left').textContent=fmt(Math.ceil(sim.duration-sim.time));const next=sim.recommendation();document.querySelector('#service-policy-label').textContent=SERVICE_RULES[sim.policy].name;document.querySelector('#next-priority').textContent=next?`Next: ${next.name}${next.isRemake?' ↻':''} →`:'No waiting orders';document.querySelector('#next-priority').disabled=!next;const remakes=sim.orders.filter(o=>o.isRemake);document.querySelector('#remake-alert').textContent=remakes.length?`↻ ${remakes.length} remake${remakes.length===1?'':'s'} waiting`:'';for(const b of document.querySelectorAll('[data-pick]')){const o=sim.orders.find(o=>o.id===+b.dataset.pick);if(!o)continue;b.classList.toggle('remake-ticket',!!o.isRemake);b.classList.toggle('priority-ticket',o.id===next?.id);b.textContent=`${o.isRemake?'↻ REMAKE · ':''}${o.name} #${o.id}${sim.ready(o)?' ✓':''}`;b.title=o.isRemake?`${o.returnReason}. Original arrival timer continues.`:o.id===next?.id?'Suggested by your service rule. You may choose another customer.':'';}const cloud=document.querySelector('#order-cloud');if(sim.active?.isRemake&&cloud&&!cloud.querySelector('.return-note'))cloud.insertAdjacentHTML('afterbegin',`<div class="return-note">↻ Please remake my order.<small>${sim.active.returnReason}. Keep any correct items.</small></div>`);};
showShop=function(){serviceShop();const next=document.querySelector('#begin-next'),continueToPrediction=next.onclick;next.onclick=()=>{storyCard('Choose how to work the queue','Your rule suggests the next customer, selects who comes next after handoff, and guides the helper. You can still choose another customer. Compare average and longest waits to see who benefits.',Object.entries(SERVICE_RULES).map(([key,rule])=>({label:rule.name,run:()=>{journey.serviceRule=key;continueToPrediction();}})));const p=document.createElement('div');p.className='service-explanations';p.innerHTML=Object.values(SERVICE_RULES).map(r=>`<p><b>${r.name}:</b> ${r.detail}</p>`).join('');document.querySelector('.story-actions').before(p);};};
handoff=function(){if(sim?.tutorial){serviceTutorialHandoff();return;}if(!sim?.ready()||servedAnimation)return;closeStation();const o=sim.active;servedAnimation=o.id;paused=true;const banner=document.querySelector('#handoff-banner');banner.hidden=false;banner.innerHTML=`<b>Checking ${o.name}’s order…</b>`;setTimeout(()=>{if(!sim||sim.finished){servedAnimation=null;return;}const r=sim.serve(o);servedAnimation=null;banner.hidden=true;paused=false;update();updateCloud(true);if(r.rework){storyCard('This order came back',`${r.name} needs a correction. A red <b>Remake</b> ticket has joined the work queue. The original waiting timer continues, and wasted ingredients cost <b>$${r.cost.toFixed(2)}</b>. Correct items are kept.<br><br>Fixing this order uses time that could serve a new customer.`,[{label:'Back to the queue →',run:()=>{}}]);}else toast(`${r.name}: ${r.satisfaction}% satisfaction · ${Math.round(r.wait)}s total wait · $${r.tip.toFixed(2)} tip`);},900);};
showReport=function(){serviceReport();const r=journey.reports.at(-1);if(!r)return;const panel=document.createElement('section');panel.className='service-review';panel.innerHTML=`<h2>Your service rule & rework</h2><p><b>${SERVICE_RULES[r.policy||'fifo'].name}</b> guided this shift.</p><div class="rework-results"><span><b>${r.returns||0}</b> returned orders</span><span><b>$${(r.remakeCost||0).toFixed(2)}</b> wasted ingredients</span><span><b>${Math.round(r.remakeSeconds||0)}s</b> active remake work</span></div></section>`;document.querySelector('.report-actions').before(panel);};
